from collections import Counter

def collect_wrangled_flags(count=10):
    """Connect to the server and collect multiple wrangled flags"""
    wrangled_flags = []

    for i in range(count):
        try:
            conn = remote("rev.chal.csaw.io", 8000)
            response = conn.recvall().decode().strip()
            conn.close()

            # Extract the wrangled flag (assuming it's on a line by itself)
            lines = response.split('\n')
            if len(lines) > 0:
                wrangled_flag = lines[-1].strip()
                if len(wrangled_flag) == 21:  # Expected length of our flag
                    wrangled_flags.append(wrangled_flag)
                    print(f"Sample {i+1}: {wrangled_flag}")

            time.sleep(1)  # Add a small delay to avoid rate limiting

        except Exception as e:
            print(f"Error connecting to server: {e}")

    return wrangled_flags

def analyze_char_positions(wrangled_flags):
    """Analyze character positions across multiple wrangled flags"""
    # Create a list of counters, one for each position in the flag
    positions = [Counter() for _ in range(21)]

    # Count character frequencies at each position
    for flag in wrangled_flags:
        for i, char in enumerate(flag):
            positions[i][char] += 1

    # Print the most common characters at each position
    for i, counter in enumerate(positions):
        print(f"Position {i}: {counter.most_common(3)}")

    return positions

def analyze_flag_characters(wrangled_flags):
    """Count the occurrences of each character across all samples"""
