        print(f"\nVerifying candidate: {candidate}")
        candidate_counts = Counter(candidate)
        valid = True

        # Check if the characters in the candidate match our expected counts
        for char, count in candidate_counts.items():
            if char_counts.get(char, 0) != count:
                valid = False
                print(f"  Character '{char}' count doesn't match: {count} vs {char_counts.get(char, 0)}")

        if valid:
